import {
  ArrowRight, BookOpen, Building2, Check, ChevronDown, CircleAlert,
  Database, FileText, Link2, LoaderCircle, LogOut, Menu, Mic2, PhoneCall,
  Plus, Radio, Search, Settings2, ShieldCheck, Sparkles, UploadCloud, UserPlus,
  Users, X, Trash2, Save, SlidersHorizontal, Eye, CircleDot,
} from "lucide-react";
import type { Session, SupabaseClient } from "@supabase/supabase-js";
import { ChangeEvent, FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { browserSupabase } from "../lib/supabase";
import { chunksOf } from "../lib/source-indexing";

type Company = { id: string; name: string; description: string; timezone: string; agent_instructions: string; current_version: number; role: string };
type Member = { id: string; user_id: string | null; email: string; display_name: string; role: string; role_label: string; status: string; region: string; locale: string; timezone: string; phone_last_four: string | null; call_consent: boolean; quiet_hours_start: string | null; quiet_hours_end: string | null; last_briefed_version: number };
type Invite = { id: string; email: string; display_name: string; role: string; role_label: string; region: string; token: string; expires_at: string; accepted_at: string | null };
type Source = { id: string; kind: string; label: string; index_status: string; chunk_count: number; byte_size: number; mime_type: string | null; storage_path: string | null; created_at: string };
type MemoryAck = { member_id: string; state: string; note: string | null; acknowledged_at: string | null };
type Memory = { id: string; version: number; kind: string; title: string; body: string; status: string; confidence: number; created_at: string; author_member_id: string | null; source_excerpt: string | null; audience: string[]; supersedes_id: string | null; acknowledgements: MemoryAck[] };
type CallSession = { id: string; mode: string; provider: string; status: string; provider_call_id: string | null; requested_at: string; member_id: string };
type CompanyJoin = { role: string; companies: Omit<Company, "role"> | Array<Omit<Company, "role">> | null };
type View = "overview" | "sources" | "memory" | "people" | "calls" | "settings";
type Modal = null | "company" | "invite" | "source" | "profile" | "call" | "memory";
type CallMode = "deposit" | "catchup" | "ask";

const regionOptions = [
  ["IN", "India"], ["US", "United States"], ["GB", "United Kingdom"], ["AE", "United Arab Emirates"],
  ["SG", "Singapore"], ["MY", "Malaysia"], ["AU", "Australia"], ["CA", "Canada"], ["DE", "Germany"],
  ["FR", "France"], ["JP", "Japan"], ["MX", "Mexico"], ["BR", "Brazil"], ["ID", "Indonesia"],
  ["PH", "Philippines"], ["KE", "Kenya"], ["ZA", "South Africa"], ["OTHER", "Other"],
];
const supportedRegions = new Set(["US","SG","MY","IN","AE","AU","CA","GB","VN","DE","JP","FR","MX","BR","ID","PH","KE"]);
const modeCopy: Record<CallMode, { label: string; description: string; icon: typeof Mic2 }> = {
  deposit: { label: "Share what's changed", description: "Talk it through naturally. CALL-E will separate facts, ideas, decisions, tasks and unknowns.", icon: Mic2 },
  catchup: { label: "Catch me up", description: "Get a concise briefing from the memory you have not seen and the sources behind it.", icon: Radio },
  ask: { label: "Work through a question", description: "Bring a problem or unresolved question; CALL-E will use company context and help clarify it.", icon: Users },
};

function initials(name: string) { return name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function timeAgo(value: string) {
  const diff = Math.max(0, Date.now() - new Date(value).getTime());
  const minutes = Math.floor(diff / 60_000);
  if (minutes < 1) return "now";
  if (minutes < 60) return `${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}
async function apiFetch(session: Session, path: string, body?: object) {
  const response = await fetch(path, {
    method: body ? "POST" : "GET",
    headers: { authorization: `Bearer ${session.access_token}`, ...(body ? { "content-type": "application/json" } : {}) },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  const result = await response.json() as Record<string, unknown>;
  if (!response.ok) throw new Error(typeof result.message === "string" ? result.message : "That request could not be completed.");
  return result;
}

export function AsyncFoundersConsole() {
  const supabase = useMemo(() => browserSupabase(), []);
  const [session, setSession] = useState<Session | null | undefined>(() => supabase ? undefined : null);

  useEffect(() => {
    if (!supabase) return;
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data } = supabase.auth.onAuthStateChange((_event, next) => setSession(next));
    return () => data.subscription.unsubscribe();
  }, [supabase]);

  if (!supabase) return <ConfigurationScreen />;
  if (session === undefined) return <LoadingScreen />;
  if (!session) return <AuthScreen supabase={supabase} />;
  return <WorkspaceApp supabase={supabase} session={session} />;
}

function LoadingScreen() {
  return <main className="center-screen"><span className="signal-mark"><i /><i /><i /></span><LoaderCircle className="spin" /><p>Opening your company memory…</p></main>;
}

function ConfigurationScreen() {
  return <main className="setup-screen"><div className="setup-card"><span className="eyebrow">DEPLOYMENT READY · CONNECTION PENDING</span><h1>Your company brain is ready to connect.</h1><p>Add the Supabase URL, public key and server key to activate accounts, isolated companies and persistent uploads. Add the CALL-E key to activate real callbacks.</p><div className="setup-list"><span><Check /> Multi-tenant product built</span><span><Check /> Row-level isolation prepared</span><span><Check /> CALL-E adapter installed</span></div></div></main>;
}

function AuthScreen({ supabase }: { supabase: SupabaseClient }) {
  const [mode, setMode] = useState<"signin" | "signup">("signup");
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");

  async function submit(event: FormEvent) {
    event.preventDefault(); setBusy(true); setMessage("");
    try {
      if (mode === "signup") {
        const { data, error } = await supabase.auth.signUp({ email: form.email, password: form.password, options: { data: { display_name: form.name } } });
        if (error) throw error;
        if (!data.session) setMessage("Check your email to confirm the account, then sign in.");
      } else {
        const { error } = await supabase.auth.signInWithPassword({ email: form.email, password: form.password });
        if (error) throw error;
      }
    } catch (error) { setMessage(error instanceof Error ? error.message : "Authentication failed."); }
    finally { setBusy(false); }
  }

  return <main className="auth-shell">
    <section className="auth-story"><a className="wordmark" href="#"><span className="signal-mark"><i /><i /><i /></span><strong>asyncfounders</strong><b>.</b></a><div><span className="eyebrow">THE ASYNC COMPANY MIDDLEMAN</span><h1>Talk once.<br />The company <em>remembers.</em></h1><p>Create a private company brain. Add your founders. Let each person speak when they are free—and keep the team on one inspectable version of reality.</p></div><div className="auth-proof"><span><ShieldCheck /> Isolated company workspaces</span><span><Database /> Source-backed memory</span><span><PhoneCall /> Real AI callbacks with consent</span></div></section>
    <section className="auth-panel"><div className="auth-card"><span className="eyebrow">{mode === "signup" ? "CREATE YOUR ACCOUNT" : "WELCOME BACK"}</span><h2>{mode === "signup" ? "Start a company brain" : "Return to your teams"}</h2><p>{mode === "signup" ? "No demo team. Your workspace starts clean." : "Sign in to continue where your team left off."}</p><form onSubmit={submit}>{mode === "signup" && <label>Your name<input required minLength={2} value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Ada Lovelace" /></label>}<label>Work email<input required type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} placeholder="you@company.com" /></label><label>Password<input required type="password" minLength={8} value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} placeholder="At least 8 characters" /></label>{message && <div className="form-message"><CircleAlert size={15} />{message}</div>}<button className="primary full" disabled={busy}>{busy ? <LoaderCircle className="spin" /> : mode === "signup" ? "Create account" : "Sign in"}<ArrowRight /></button></form><button className="text-button" onClick={() => { setMode(mode === "signup" ? "signin" : "signup"); setMessage(""); }}>{mode === "signup" ? "Already have an account? Sign in" : "New here? Create an account"}</button></div></section>
  </main>;
}

function WorkspaceApp({ supabase, session }: { supabase: SupabaseClient; session: Session }) {
  const [companies, setCompanies] = useState<Company[]>([]);
  const [companyId, setCompanyId] = useState("");
  const [members, setMembers] = useState<Member[]>([]);
  const [invites, setInvites] = useState<Invite[]>([]);
  const [sources, setSources] = useState<Source[]>([]);
  const [memories, setMemories] = useState<Memory[]>([]);
  const [calls, setCalls] = useState<CallSession[]>([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState<Modal>(null);
  const [view, setView] = useState<View>("overview");
  const [companyMenu, setCompanyMenu] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [toast, setToast] = useState("");
  const company = companies.find((item) => item.id === companyId) ?? companies[0];

  const flash = useCallback((text: string) => { setToast(text); window.setTimeout(() => setToast(""), 3200); }, []);
  const loadCompanies = useCallback(async () => {
    const { data, error } = await supabase.from("company_members").select("role, companies(id,name,description,timezone,agent_instructions,current_version)").eq("user_id", session.user.id).eq("status", "active");
    if (error) throw error;
    const rows = (data ?? []) as unknown as CompanyJoin[];
    const next = rows.flatMap((row) => {
      const records = Array.isArray(row.companies) ? row.companies : row.companies ? [row.companies] : [];
      return records.map((item) => ({ ...item, role: row.role }));
    });
    setCompanies(next);
    setCompanyId((current) => next.some((item) => item.id === current) ? current : next[0]?.id ?? "");
    return next;
  }, [session.user.id, supabase]);

  const loadWorkspace = useCallback(async (id: string) => {
    if (!id) { setMembers([]); setInvites([]); setSources([]); setMemories([]); setCalls([]); return; }
    const [memberRes, inviteRes, sourceRes, memoryRes, callRes] = await Promise.all([
      supabase.from("company_members").select("id,user_id,email,display_name,role,role_label,status,region,locale,timezone,phone_last_four,call_consent,quiet_hours_start,quiet_hours_end,last_briefed_version").eq("company_id", id).order("created_at"),
      supabase.from("company_invites").select("id,email,display_name,role,role_label,region,token,expires_at,accepted_at").eq("company_id", id).is("accepted_at", null).order("created_at", { ascending: false }),
      supabase.from("sources").select("id,kind,label,index_status,chunk_count,byte_size,mime_type,storage_path,created_at").eq("company_id", id).order("created_at", { ascending: false }),
      supabase.from("memory_items").select("id,version,kind,title,body,status,confidence,created_at,author_member_id,source_excerpt,audience,supersedes_id,acknowledgements(member_id,state,note,acknowledged_at)").eq("company_id", id).order("version", { ascending: false }).limit(200),
      supabase.from("call_sessions").select("id,mode,provider,status,provider_call_id,requested_at,member_id").eq("company_id", id).order("requested_at", { ascending: false }).limit(40),
    ]);
    const issue = [memberRes, inviteRes, sourceRes, memoryRes, callRes].find((item) => item.error)?.error;
    if (issue) throw issue;
    setMembers((memberRes.data ?? []) as Member[]); setInvites((inviteRes.data ?? []) as Invite[]); setSources((sourceRes.data ?? []) as Source[]); setMemories((memoryRes.data ?? []) as Memory[]); setCalls((callRes.data ?? []) as CallSession[]);
  }, [supabase]);

  useEffect(() => { void Promise.resolve().then(() => loadCompanies()).catch((error) => flash(error.message)).finally(() => setLoading(false)); }, [flash, loadCompanies]);
  useEffect(() => { if (companyId) void Promise.resolve().then(() => loadWorkspace(companyId)).catch((error) => flash(error.message)); }, [companyId, flash, loadWorkspace]);
  useEffect(() => {
    const token = new URLSearchParams(window.location.search).get("invite");
    if (!token) return;
    supabase.rpc("accept_invite", { invite_token: token }).then(({ error }) => {
      if (error) flash(error.message); else { flash("Invite accepted. Welcome to the company."); loadCompanies(); }
      history.replaceState({}, "", window.location.pathname);
    });
  }, [flash, loadCompanies, supabase]);

  if (loading) return <LoadingScreen />;
  if (!companies.length) return <EmptyOnboarding supabase={supabase} session={session} onCreated={async () => { await loadCompanies(); }} />;

  const currentMember = members.find((member) => member.user_id === session.user.id);
  const unseen = Math.max(0, (company?.current_version ?? 0) - (currentMember?.last_briefed_version ?? 0));
  const openDecisions = memories.filter((memory) => ["decision", "conflict", "question"].includes(memory.kind) && !["resolved", "answered", "dismissed"].includes(memory.status));

  return <div className="product-shell">
    <header className="app-header"><button className="wordmark button-reset" onClick={() => setView("overview")}><span className="signal-mark"><i /><i /><i /></span><strong>asyncfounders</strong><b>.</b></button><div className="company-picker"><button onClick={() => setCompanyMenu(!companyMenu)}><span className="company-glyph">{company.name[0]}</span><span><small>COMPANY</small><strong>{company.name}</strong></span><ChevronDown /></button>{companyMenu && <div className="company-dropdown">{companies.map((item) => <button key={item.id} className={item.id === company.id ? "active" : ""} onClick={() => { setCompanyId(item.id); setCompanyMenu(false); setView("overview"); }}><span>{item.name[0]}</span><div><strong>{item.name}</strong><small>{item.role} · v{item.current_version}</small></div>{item.id === company.id && <Check />}</button>)}<button className="add-company" onClick={() => { setModal("company"); setCompanyMenu(false); }}><Plus /> New company</button></div>}</div><nav className={mobileMenu ? "open" : ""}>{(["overview","sources","memory","people","calls","settings"] as View[]).map((item) => <button key={item} className={view === item ? "active" : ""} onClick={() => { setView(item); setMobileMenu(false); }}>{item}</button>)}</nav><div className="header-right"><button className="call-button" onClick={() => setModal("call")}><PhoneCall /> Call me</button><button className="icon-button" onClick={() => setModal("profile")} aria-label="My callback settings"><Settings2 /></button><button className="icon-button mobile-only" onClick={() => setMobileMenu(!mobileMenu)} aria-label="Menu">{mobileMenu ? <X /> : <Menu />}</button></div></header>

    <main>
      {view === "overview" && <Overview company={company} members={members} sources={sources} memories={memories} unseen={unseen} openDecisions={openDecisions} onAction={setModal} onView={setView} />}
      {view === "sources" && <SourcesView sources={sources} onAdd={() => setModal("source")} onIndex={async (source) => { try { await apiFetch(session,source.kind === "link" ? "/api/sources/index-link" : "/api/sources/index",{companyId:company.id,sourceId:source.id});await loadWorkspace(company.id);flash(`${source.label} is now searchable.`); } catch(issue) { flash(issue instanceof Error?issue.message:"The source could not be indexed."); } }} />}
      {view === "memory" && currentMember && <MemoryView memories={memories} members={members} currentMember={currentMember} supabase={supabase} onAdd={() => setModal("memory")} onChanged={() => loadWorkspace(company.id)} />}
      {view === "people" && <PeopleView members={members} invites={invites} onInvite={() => setModal("invite")} />}
      {view === "calls" && <CallsView calls={calls} members={members} onCall={() => setModal("call")} />}
      {view === "settings" && <SettingsView key={company.id} company={company} session={session} supabase={supabase} onSaved={async () => { await loadCompanies(); flash("Company settings saved."); }} onDeleted={async () => { await loadCompanies(); setView("overview"); flash("Company deleted."); }} />}
    </main>
    <footer><span>AsyncFounders</span><p>Evidence-backed team memory—not a transcript archive.</p><button onClick={() => supabase.auth.signOut()}><LogOut /> Sign out</button></footer>
    {toast && <div className="toast"><Check />{toast}</div>}
    {modal === "company" && <CompanyModal supabase={supabase} onClose={() => setModal(null)} onDone={async (id) => { await loadCompanies(); setCompanyId(id); setModal(null); flash("Company created. Its memory is isolated and ready."); }} />}
    {modal === "invite" && <InviteModal supabase={supabase} session={session} company={company} onClose={() => setModal(null)} onDone={async () => { await loadWorkspace(company.id); setModal(null); flash("Founder invited. Share the secure invite link."); }} />}
    {modal === "source" && <SourceModal supabase={supabase} session={session} company={company} onClose={() => setModal(null)} onDone={async () => { await loadWorkspace(company.id); setModal(null); flash("Source added to this company brain."); }} />}
    {modal === "memory" && <MemoryModal supabase={supabase} company={company} onClose={() => setModal(null)} onDone={async () => { await loadCompanies(); await loadWorkspace(company.id); setModal(null); flash("Company memory version created."); }} />}
    {modal === "profile" && currentMember && <ProfileModal session={session} company={company} member={currentMember} onClose={() => setModal(null)} onDone={async () => { await loadWorkspace(company.id); setModal(null); flash("Callback settings updated."); }} />}
    {modal === "call" && currentMember && <CallModal session={session} company={company} member={currentMember} onClose={() => setModal(null)} onDone={async () => { await loadWorkspace(company.id); flash("Call state updated."); }} />}
  </div>;
}

function EmptyOnboarding({ supabase, onCreated }: { supabase: SupabaseClient; session: Session; onCreated: () => Promise<void> }) {
  const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); const { error: issue } = await supabase.rpc("create_company", { company_name: name, company_description: description, company_timezone: Intl.DateTimeFormat().resolvedOptions().timeZone }); if (issue) setError(issue.message); else await onCreated(); setBusy(false); }
  return <main className="onboarding"><a className="wordmark" href="#"><span className="signal-mark"><i /><i /><i /></span><strong>asyncfounders</strong><b>.</b></a><div className="onboarding-grid"><section><span className="eyebrow">YOUR FIRST COMPANY</span><h1>Give the team<br />one shared <em>memory.</em></h1><p>Create a clean workspace. Then add founders, sources and callback consent—without mixing this company with any other team you belong to.</p><div className="flow-line"><span>01<br /><b>Create</b></span><ArrowRight /><span>02<br /><b>Invite</b></span><ArrowRight /><span>03<br /><b>Call</b></span></div></section><form onSubmit={submit}><label>Company name<input required minLength={2} value={name} onChange={(event) => setName(event.target.value)} placeholder="Acme Labs" autoFocus /></label><label>What are you building?<textarea required minLength={12} value={description} onChange={(event) => setDescription(event.target.value)} placeholder="A short, factual description of the company." /></label>{error && <div className="form-message"><CircleAlert />{error}</div>}<button className="primary full" disabled={busy}>{busy ? <LoaderCircle className="spin" /> : <Building2 />}Create company</button></form></div></main>;
}

function Overview({ company, members, sources, memories, unseen, openDecisions, onAction, onView }: { company: Company; members: Member[]; sources: Source[]; memories: Memory[]; unseen: number; openDecisions: Memory[]; onAction: (modal: Modal) => void; onView: (view: View) => void }) {
  return <><section className="hero"><div className="dot-field" /><div className="hero-copy"><span className="eyebrow"><Sparkles /> LIVE COMPANY STATE · VERSION {company.current_version}</span><h1>Everything {company.name}<br />knows—ready for <em>whoever needs it.</em></h1><p>{company.description}</p><div className="hero-actions"><button className="primary" onClick={() => onAction("call")}><PhoneCall /> Talk to CALL-E</button><button className="secondary" onClick={() => onAction("source")}><UploadCloud /> Add knowledge</button></div></div><div className="brain-visual"><div className="brain-core"><Database /><b>{sources.reduce((sum, item) => sum + item.chunk_count, 0)}</b><span>INDEXED CHUNKS</span></div>{members.slice(0,4).map((member,index) => <div className={`brain-person p${index+1}`} key={member.id}><span>{initials(member.display_name)}</span><small>{member.display_name}</small></div>)}</div></section>
    <section className="pulse-grid"><button onClick={() => onView("memory")}><small>YOUR KNOWLEDGE GAP</small><strong>{unseen}</strong><span>company updates not yet acknowledged <ArrowRight /></span></button><button onClick={() => onView("memory")}><small>OPEN DECISIONS</small><strong>{openDecisions.length}</strong><span>questions or conflicts need closure <ArrowRight /></span></button><button onClick={() => onView("sources")}><small>SOURCE COVERAGE</small><strong>{sources.length}</strong><span>files, notes and links in this brain <ArrowRight /></span></button><button onClick={() => onView("people")}><small>TEAM</small><strong>{members.filter((item) => item.status === "active").length}</strong><span>active people, one company state <ArrowRight /></span></button></section>
    <section className="middleman"><div><span className="eyebrow">THE MIDDLEMAN</span><h2>People speak at different times.<br />The company stays synchronized.</h2></div><ol><li><b>01</b><span><UploadCloud /> Sources enter</span><p>Notes, files and links remain attached to the company that owns them.</p></li><li><b>02</b><span><Database /> Memory compounds</span><p>Facts, proposals, decisions and conflicts stay typed and inspectable.</p></li><li><b>03</b><span><PhoneCall /> Founders receive</span><p>Web or phone delivers only the relevant knowledge delta.</p></li></ol></section>
    <section className="latest-section"><div className="section-heading"><div><span className="eyebrow">LATEST COMPANY MEMORY</span><h2>What changed, with receipts.</h2></div><button className="secondary" onClick={() => onView("memory")}>View full ledger <ArrowRight /></button></div><div className="memory-list">{memories.slice(0,5).map((item) => <MemoryRow key={item.id} item={item} members={members} />)}{!memories.length && <EmptyState icon={BookOpen} title="No company memory yet" copy="Add a source or complete the first founder callback." />}</div></section></>;
}

function SourcesView({ sources, onAdd, onIndex }: { sources: Source[]; onAdd: () => void; onIndex: (source: Source) => Promise<void> }) { const [indexing,setIndexing]=useState("");return <Page title="Company sources" eyebrow="PRIVATE · INDEXED · CALL-E READY" action={<button className="primary" onClick={onAdd}><Plus /> Add source</button>}><div className="source-grid">{sources.map((source) => {const recoverable=source.index_status!=="indexed"&&((source.mime_type==="application/pdf"&&Boolean(source.storage_path))||source.kind==="link");return <article key={source.id}><div className="source-icon">{source.kind === "link" ? <Link2 /> : <FileText />}</div><div><small>{source.kind.toUpperCase()} · {timeAgo(source.created_at)}</small><h3>{source.label}</h3><p>{source.chunk_count} searchable chunks · {source.byte_size ? `${Math.ceil(source.byte_size / 1024)} KB` : "awaiting index"}</p>{recoverable&&<button className="copy-link" disabled={Boolean(indexing)} onClick={async()=>{setIndexing(source.id);try{await onIndex(source);}finally{setIndexing("");}}}>{indexing===source.id?"Indexing…":"Index now"}</button>}</div><span className={`status ${source.index_status}`}>{source.index_status}</span></article>;})}{!sources.length && <EmptyState icon={UploadCloud} title="This brain has no sources" copy="Upload a text, markdown, CSV, JSON or PDF file; paste notes; or add a public link. Indexed content becomes usable in CALL-E conversations." action={onAdd} />}</div></Page>; }

function MemoryView({ memories, members, currentMember, supabase, onAdd, onChanged }: { memories: Memory[]; members: Member[]; currentMember: Member; supabase: SupabaseClient; onAdd: () => void; onChanged: () => Promise<void> }) {
  const [query,setQuery]=useState(""); const [kind,setKind]=useState("all"); const [status,setStatus]=useState("all"); const [personal,setPersonal]=useState(false); const [busy,setBusy]=useState("");
  const ackFor=(item:Memory)=>item.acknowledgements?.find((ack)=>ack.member_id===currentMember.id)?.state??"unseen";
  const filtered=memories.filter((item)=>`${item.title} ${item.body} ${item.source_excerpt??""}`.toLowerCase().includes(query.toLowerCase())&&(kind==="all"||item.kind===kind)&&(status==="all"||item.status===status)&&(!personal||ackFor(item)!=="acknowledged"));
  async function setAck(item:Memory,next:string){setBusy(item.id);const {error}=await supabase.from("acknowledgements").upsert({memory_item_id:item.id,member_id:currentMember.id,state:next,acknowledged_at:next==="acknowledged"?new Date().toISOString():null},{onConflict:"memory_item_id,member_id"});setBusy("");if(!error)await onChanged();}
  const open=memories.filter((item)=>["open","proposed"].includes(item.status)).length; const evidence=memories.filter((item)=>Boolean(item.source_excerpt)).length; const unseen=memories.filter((item)=>ackFor(item)==="unseen").length;
  return <Page title="Memory ledger" eyebrow="VERSIONED · EVIDENCE-LINKED · ACKNOWLEDGED" action={<button className="primary" onClick={onAdd}><Plus/>Add memory</button>}>
    <div className="memory-metrics"><span><small>VERSION</small><b>{memories[0]?.version??0}</b></span><span><small>OPEN</small><b>{open}</b></span><span><small>UNSEEN BY YOU</small><b>{unseen}</b></span><span><small>WITH EVIDENCE</small><b>{evidence}</b></span></div>
    <div className="memory-toolbar"><label className="search"><Search/><input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Search titles, detail or evidence"/></label><label><SlidersHorizontal/>Type<select value={kind} onChange={(event)=>setKind(event.target.value)}><option value="all">All types</option>{["fact","idea","assumption","decision","question","task","conflict"].map((value)=><option key={value}>{value}</option>)}</select></label><label>Status<select value={status} onChange={(event)=>setStatus(event.target.value)}><option value="all">All states</option>{["open","proposed","accepted","answered","resolved","superseded","dismissed"].map((value)=><option key={value}>{value}</option>)}</select></label><button className={personal?"filter-active":""} onClick={()=>setPersonal(!personal)}><Eye/>Needs my review</button></div>
    <div className="memory-list">{filtered.map((item)=><MemoryRow key={item.id} item={item} members={members} ackState={ackFor(item)} busy={busy===item.id} onAck={(next)=>setAck(item,next)}/>)}{!filtered.length&&<EmptyState icon={BookOpen} title="No matching memory" copy="Change the filters or add a typed, evidence-backed company update." />}</div>
  </Page>;
}
function PeopleView({ members, invites, onInvite }: { members: Member[]; invites: Invite[]; onInvite: () => void }) { return <Page title="Founders & teammates" eyebrow="MEMBERSHIP IS NOT A PHONE REGION" action={<button className="primary" onClick={onInvite}><UserPlus /> Invite founder</button>}><div className="people-grid">{members.map((member)=><article key={member.id}><span className="avatar">{initials(member.display_name)}</span><div><small>{member.role.toUpperCase()}</small><h3>{member.display_name}</h3><p>{member.role_label} · {member.timezone}</p><span className={member.call_consent?"voice-ready":"voice-off"}>{member.call_consent?<><PhoneCall /> Callback ready · •••• {member.phone_last_four}</>:<><ShieldCheck /> Web access · voice not enabled</>}</span></div></article>)}{invites.map((invite)=><article className="pending" key={invite.id}><span className="avatar">{initials(invite.display_name)}</span><div><small>PENDING INVITE</small><h3>{invite.display_name}</h3><p>{invite.email} · expires {new Date(invite.expires_at).toLocaleDateString()}</p><button className="copy-link" onClick={()=>navigator.clipboard.writeText(`${location.origin}/login?invite=${invite.token}`)}>Copy invite link</button></div></article>)}</div></Page>; }
function CallsView({ calls, members, onCall }: { calls: CallSession[]; members: Member[]; onCall: () => void }) { return <Page title="Callback sessions" eyebrow="SELF-DIRECTED · PREVIEWED · IDEMPOTENT" action={<button className="primary" onClick={onCall}><PhoneCall /> Call me</button>}><div className="call-list">{calls.map((call)=>{const member=members.find((item)=>item.id===call.member_id);return <article key={call.id}><span className={`call-dot ${call.status}`} /><div><small>{call.mode.toUpperCase()} · {call.provider}</small><h3>{member?.display_name??"Team member"}</h3><p>{timeAgo(call.requested_at)} · {call.status.replaceAll("_"," ")}</p></div><span className="status">{call.status}</span></article>;})}{!calls.length&&<EmptyState icon={PhoneCall} title="No callbacks yet" copy="Choose what you need, review the context boundary, then explicitly confirm a call to your own verified number." action={onCall} />}</div></Page>; }
function SettingsView({ company, session, supabase, onSaved, onDeleted }: { company: Company; session: Session; supabase: SupabaseClient; onSaved: () => Promise<void>; onDeleted: () => Promise<void> }) {
  const [form,setForm]=useState({name:company.name,description:company.description,timezone:company.timezone,agent_instructions:company.agent_instructions??""}); const [confirmation,setConfirmation]=useState(""); const [busy,setBusy]=useState(""); const [error,setError]=useState("");
  const canManage=["founder","admin"].includes(company.role);
  async function save(event:FormEvent){event.preventDefault();setBusy("save");setError("");const {error:issue}=await supabase.from("companies").update({...form,updated_at:new Date().toISOString()}).eq("id",company.id);if(issue)setError(issue.message);else await onSaved();setBusy("");}
  async function remove(){setBusy("delete");setError("");try{await apiFetch(session,"/api/company/delete",{companyId:company.id,confirmation});await onDeleted();}catch(issue){setError(issue instanceof Error?issue.message:"Company deletion failed.");}setBusy("");}
  return <Page title="Company settings" eyebrow="TEAM-WIDE OPERATING CONTEXT" action={<span className="settings-role">{company.role}</span>}><div className="settings-layout"><form className="settings-card" onSubmit={save}><h2>Workspace</h2><p>These settings shape the shared company context and every future CALL-E briefing.</p><label>Company name<input required minLength={2} maxLength={80} disabled={!canManage} value={form.name} onChange={(event)=>setForm({...form,name:event.target.value})}/></label><label>What the company is building<textarea required minLength={12} disabled={!canManage} value={form.description} onChange={(event)=>setForm({...form,description:event.target.value})}/></label><label>Company timezone<input required disabled={!canManage} value={form.timezone} onChange={(event)=>setForm({...form,timezone:event.target.value})}/></label><label>How CALL-E should work with this company<textarea rows={7} maxLength={4000} disabled={!canManage} value={form.agent_instructions} onChange={(event)=>setForm({...form,agent_instructions:event.target.value})} placeholder="Company vocabulary, current priorities, areas to probe carefully, and context the agent should always retain."/><small>CALL-E still preserves uncertainty, consent, approval and typed memory boundaries.</small></label>{error&&<div className="form-message"><CircleAlert/>{error}</div>}<button className="primary" disabled={!canManage||Boolean(busy)}>{busy==="save"?<LoaderCircle className="spin"/>:<Save/>}Save company settings</button></form><section className="danger-card"><span className="eyebrow">DANGER ZONE</span><h2>Delete company</h2><p>Permanently removes this company’s members, sources, indexed chunks, calls, memory and stored files. Other companies stay untouched.</p><label>Type <b>{company.name}</b> to confirm<input disabled={!canManage} value={confirmation} onChange={(event)=>setConfirmation(event.target.value)}/></label><button className="danger-button" disabled={!canManage||confirmation!==company.name||Boolean(busy)} onClick={remove}>{busy==="delete"?<LoaderCircle className="spin"/>:<Trash2/>}Delete company permanently</button></section></div></Page>;
}
function Page({ title, eyebrow, action, children }: { title: string; eyebrow: string; action: React.ReactNode; children: React.ReactNode }) { return <section className="page-view"><div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1></div>{action}</div>{children}</section>; }
function MemoryRow({ item, members, ackState, busy, onAck }: { item: Memory; members: Member[]; ackState?: string; busy?: boolean; onAck?: (state:string)=>void }) { const [expanded,setExpanded]=useState(false);const author=members.find((member)=>member.id===item.author_member_id);return <article className={`memory-row ${expanded?"expanded":""}`}><span className={`memory-kind ${item.kind}`}>{item.kind}</span><div><small>VERSION {item.version} · {author?.display_name??"Company source"} · {timeAgo(item.created_at)}</small><button className="memory-title" onClick={()=>setExpanded(!expanded)}><h3>{item.title}</h3><ChevronDown/></button><p>{item.body}</p>{expanded&&<div className="memory-detail"><span><b>Confidence</b>{Math.round(Number(item.confidence)*100)}%</span><span><b>Audience</b>{Array.isArray(item.audience)?item.audience.join(", "):"team"}</span><span><b>Your state</b>{ackState??"not tracked"}</span>{item.source_excerpt&&<blockquote><b>Evidence</b>{item.source_excerpt}</blockquote>}{onAck&&<div className="ack-actions"><button disabled={busy} onClick={()=>onAck("acknowledged")}><Check/>Acknowledge</button><button disabled={busy} onClick={()=>onAck("deferred")}><CircleDot/>Defer</button><button disabled={busy} onClick={()=>onAck("disputed")}><CircleAlert/>Dispute</button></div>}</div>}</div><span className="memory-state">{item.status}</span></article>; }
function EmptyState({ icon: Icon, title, copy, action }: { icon: typeof BookOpen; title: string; copy: string; action?: () => void }) { return <div className="empty-state"><Icon /><h3>{title}</h3><p>{copy}</p>{action&&<button className="secondary" onClick={action}><Plus /> Add the first one</button>}</div>; }

function ModalShell({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode }) { return <div className="modal-backdrop" onMouseDown={(event)=>{if(event.target===event.currentTarget)onClose();}}><section className="modal-card" role="dialog" aria-modal="true"><button className="modal-close" onClick={onClose} aria-label="Close"><X /></button><span className="eyebrow">{eyebrow}</span><h2>{title}</h2>{children}</section></div>; }
function CompanyModal({ supabase, onClose, onDone }: { supabase: SupabaseClient; onClose: () => void; onDone: (id: string) => Promise<void> }) { const [form,setForm]=useState({name:"",description:""});const [busy,setBusy]=useState(false);const [error,setError]=useState("");async function submit(event:FormEvent){event.preventDefault();setBusy(true);const {data,error:issue}=await supabase.rpc("create_company",{company_name:form.name,company_description:form.description,company_timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});if(issue)setError(issue.message);else await onDone(String(data));setBusy(false);}return <ModalShell title="Create another company" eyebrow="ISOLATED WORKSPACE" onClose={onClose}><p className="modal-intro">Membership, sources, memory and calls never cross company boundaries.</p><form onSubmit={submit}><label>Company name<input required minLength={2} value={form.name} onChange={(event)=>setForm({...form,name:event.target.value})} /></label><label>Description<textarea required minLength={12} value={form.description} onChange={(event)=>setForm({...form,description:event.target.value})} /></label>{error&&<div className="form-message">{error}</div>}<button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Building2/>}Create company</button></form></ModalShell>; }
function InviteModal({ supabase, session, company, onClose, onDone }: { supabase: SupabaseClient; session: Session; company: Company; onClose: () => void; onDone: () => Promise<void> }) { const [form,setForm]=useState({display_name:"",email:"",role:"founder",role_label:"Co-founder",region:"IN",locale:"en-IN"});const [busy,setBusy]=useState(false);const [error,setError]=useState("");async function submit(event:FormEvent){event.preventDefault();setBusy(true);const {error:issue}=await supabase.from("company_invites").insert({company_id:company.id,...form,email:form.email.toLowerCase(),invited_by:session.user.id});if(issue)setError(issue.message);else await onDone();setBusy(false);}const voice=supportedRegions.has(form.region);return <ModalShell title="Invite a founder" eyebrow="COMPANY ACCESS FIRST" onClose={onClose}><p className="modal-intro">They receive full workspace access after accepting. Phone availability is a separate channel.</p><form onSubmit={submit}><div className="form-grid"><label>Name<input required value={form.display_name} onChange={(event)=>setForm({...form,display_name:event.target.value})}/></label><label>Email<input required type="email" value={form.email} onChange={(event)=>setForm({...form,email:event.target.value})}/></label><label>Company role<select value={form.role} onChange={(event)=>setForm({...form,role:event.target.value})}><option value="founder">Founder</option><option value="admin">Admin</option><option value="member">Member</option></select></label><label>Role title<input required value={form.role_label} onChange={(event)=>setForm({...form,role_label:event.target.value})}/></label><label>Country<select value={form.region} onChange={(event)=>setForm({...form,region:event.target.value})}>{regionOptions.map(([code,label])=><option key={code} value={code}>{label}</option>)}</select></label><label>Language locale<input value={form.locale} onChange={(event)=>setForm({...form,locale:event.target.value})}/></label></div><div className={voice?"eligibility yes":"eligibility no"}>{voice?<><PhoneCall/>CALL-E supports this region; the member can opt in after joining.</>:<><ShieldCheck/>Workspace access works here; CALL-E voice is currently unavailable.</>}</div>{error&&<div className="form-message">{error}</div>}<button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin"/>:<UserPlus/>}Create secure invite</button></form></ModalShell>; }
function MemoryModal({ supabase, company, onClose, onDone }: { supabase: SupabaseClient; company: Company; onClose: () => void; onDone: () => Promise<void> }) { const [form,setForm]=useState({kind:"fact",title:"",body:"",status:"open",confidence:"0.8",evidence:"",audience:"team"});const [busy,setBusy]=useState(false);const [error,setError]=useState("");async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError("");const {error:issue}=await supabase.rpc("create_memory_item",{target_company:company.id,memory_type:form.kind,memory_title:form.title,memory_body:form.body,memory_status:form.status,memory_confidence:Number(form.confidence),memory_evidence:form.evidence,memory_audience:form.audience.split(",").map((value)=>value.trim()).filter(Boolean)});if(issue)setError(issue.message);else await onDone();setBusy(false);}return <ModalShell title="Add company memory" eyebrow="ONE TYPED VERSION AT A TIME" onClose={onClose}><p className="modal-intro">Record what is known without turning a proposal into a decision or erasing disagreement.</p><form onSubmit={submit}><div className="form-grid"><label>Type<select value={form.kind} onChange={(event)=>setForm({...form,kind:event.target.value})}>{["fact","idea","assumption","decision","question","task","conflict"].map((value)=><option key={value}>{value}</option>)}</select></label><label>Lifecycle state<select value={form.status} onChange={(event)=>setForm({...form,status:event.target.value})}>{["open","proposed","accepted","answered","resolved","dismissed"].map((value)=><option key={value}>{value}</option>)}</select></label></div><label>Title<input required minLength={2} maxLength={180} value={form.title} onChange={(event)=>setForm({...form,title:event.target.value})}/></label><label>What should the team retain?<textarea required minLength={2} maxLength={4000} rows={6} value={form.body} onChange={(event)=>setForm({...form,body:event.target.value})}/></label><label>Evidence or provenance<textarea maxLength={800} value={form.evidence} onChange={(event)=>setForm({...form,evidence:event.target.value})} placeholder="Link, observation, customer quote, call excerpt, or why this is still an assumption."/></label><div className="form-grid"><label>Confidence<select value={form.confidence} onChange={(event)=>setForm({...form,confidence:event.target.value})}><option value="0.95">Very high</option><option value="0.8">High</option><option value="0.6">Medium</option><option value="0.35">Low</option></select></label><label>Audience<input value={form.audience} onChange={(event)=>setForm({...form,audience:event.target.value})} placeholder="team, product"/></label></div>{error&&<div className="form-message"><CircleAlert/>{error}</div>}<button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Database/>}Create next version</button></form></ModalShell>; }
function SourceModal({ supabase, session, company, onClose, onDone }: { supabase: SupabaseClient; session: Session; company: Company; onClose: () => void; onDone: () => Promise<void> }) {
  const [kind,setKind]=useState<"file"|"text"|"link">("file"); const [label,setLabel]=useState(""); const [content,setContent]=useState(""); const [url,setUrl]=useState(""); const [file,setFile]=useState<File|null>(null); const [busy,setBusy]=useState(false); const [error,setError]=useState(""); const isPdf=Boolean(file&&(file.type==="application/pdf"||/\.pdf$/i.test(file.name)));
  async function chooseFile(event:ChangeEvent<HTMLInputElement>){const selected=event.target.files?.[0]??null;if(!selected)return;setError("");if(selected.size>10*1024*1024){setFile(null);setContent("");setError("Keep each file under 10 MB.");return;}setFile(selected);setLabel(selected.name);if(selected.type.startsWith("text/")||/\.(md|txt|csv|json)$/i.test(selected.name))setContent(await selected.text());else setContent("");}
  async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError("");try{
    if(kind==="link"){await apiFetch(session,"/api/sources/index-link",{companyId:company.id,url,label});await onDone();return;}
    let storage_path:string|null=null;if(file){storage_path=`${company.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,"-")}`;const {error:uploadError}=await supabase.storage.from("company-sources").upload(storage_path,file,{contentType:isPdf?"application/pdf":file.type||"application/octet-stream",upsert:false});if(uploadError)throw uploadError;if(isPdf){await apiFetch(session,"/api/sources/index",{companyId:company.id,storagePath:storage_path,label,mimeType:"application/pdf"});await onDone();return;}}
    const chunks=chunksOf(content);if(!chunks.length)throw new Error("No readable text was found in that file.");const {data:source,error:sourceError}=await supabase.from("sources").insert({company_id:company.id,kind,label,storage_path,mime_type:file?.type??"text/plain",byte_size:file?.size??new Blob([content]).size,index_status:"queued",chunk_count:0,added_by:session.user.id}).select("id").single();if(sourceError)throw sourceError;const {error:chunkError}=await supabase.from("source_chunks").insert(chunks.map((text,ordinal)=>({source_id:source.id,company_id:company.id,ordinal,content:text})));if(chunkError){await supabase.from("sources").delete().eq("id",source.id);throw chunkError;}const {error:updateError}=await supabase.from("sources").update({index_status:"indexed",chunk_count:chunks.length}).eq("id",source.id);if(updateError)throw updateError;await onDone();
  }catch(issue){setError(issue instanceof Error?issue.message:"Upload failed.");}finally{setBusy(false);}}
  return <ModalShell title="Add company knowledge" eyebrow="SOURCE-BACKED · SEARCHABLE BY CALL-E" onClose={onClose}><div className="segmented">{(["file","text","link"] as const).map((item)=><button type="button" key={item} className={kind===item?"active":""} onClick={()=>setKind(item)}>{item}</button>)}</div><form onSubmit={submit}>{kind==="file"&&<label className="dropzone"><UploadCloud/><b>{file?.name??"Choose a file"}</b><span>TXT, MD, CSV, JSON or PDF · max 10 MB</span><input required type="file" accept=".txt,.md,.csv,.json,.pdf,text/*,application/pdf" onChange={chooseFile}/></label>}<label>Source title<input required value={label} onChange={(event)=>setLabel(event.target.value)} placeholder="Product brief — August"/></label>{kind==="text"&&<label>Paste knowledge<textarea required minLength={10} rows={8} value={content} onChange={(event)=>setContent(event.target.value)} placeholder="Decisions, research, operating context…"/></label>}{kind==="link"&&<><label>Public URL<input required type="url" value={url} onChange={(event)=>setUrl(event.target.value)} placeholder="https://…"/></label><div className="eligibility yes">{busy?<LoaderCircle className="spin"/>:<Link2/>}{busy?"Fetching, cleaning and indexing the page…":"The page text will be fetched server-side, chunked and made available to CALL-E."}</div></>}{kind==="file"&&isPdf&&<div className="eligibility yes">{busy?<LoaderCircle className="spin"/>:<Database/>}{busy?"Extracting and indexing this PDF…":"Selectable PDF text will be extracted and indexed when you add it."}</div>}{error&&<div className="form-message"><CircleAlert/>{error}</div>}<button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Database/>}{busy?"Indexing source…":"Add and index source"}</button></form></ModalShell>;
}
function ProfileModal({ session, company, member, onClose, onDone }: { session: Session; company: Company; member: Member; onClose: () => void; onDone: () => Promise<void> }) {
  const [phone,setPhone]=useState(""); const [consent,setConsent]=useState(member.call_consent); const [timezone,setTimezone]=useState(member.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone); const [quietStart,setQuietStart]=useState(member.quiet_hours_start?.slice(0,5)??""); const [quietEnd,setQuietEnd]=useState(member.quiet_hours_end?.slice(0,5)??""); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError("");if(consent&&!member.phone_last_four&&!/^\+[1-9]\d{7,14}$/.test(phone)){setError("Enter your phone in E.164 format, for example +919876543210.");setBusy(false);return;}if(phone&&!/^\+[1-9]\d{7,14}$/.test(phone)){setError("Enter the new number in E.164 format, including the country code.");setBusy(false);return;}if(Boolean(quietStart)!==Boolean(quietEnd)){setError("Set both quiet-hours times, or leave both blank.");setBusy(false);return;}try{await apiFetch(session,"/api/profile",{companyId:company.id,phone,consent,timezone,quietHoursStart:quietStart||null,quietHoursEnd:quietEnd||null});await onDone();}catch(issue){setError(issue instanceof Error?issue.message:"Callback settings could not be saved.");}setBusy(false);}
  return <ModalShell title="My callback settings" eyebrow="BOUND TO MY ACCOUNT · PRIVATE · CONSENTED" onClose={onClose}><p className="modal-intro">CALL-E can only call your authenticated membership here. Your full number is never returned to another browser, and another account cannot claim it.</p><form onSubmit={submit}><label>Timezone<input required value={timezone} onChange={(event)=>setTimezone(event.target.value)}/></label><div className="form-grid"><label>Quiet hours start <small>Optional</small><input type="time" value={quietStart} onChange={(event)=>setQuietStart(event.target.value)}/></label><label>Quiet hours end <small>Optional</small><input type="time" value={quietEnd} onChange={(event)=>setQuietEnd(event.target.value)}/></label></div><small>CALL-E will refuse to dispatch during this window in your selected timezone.</small><label className="toggle-row"><input type="checkbox" checked={consent} onChange={(event)=>setConsent(event.target.checked)}/><span><b>Allow AI callbacks to me</b><small>Every call still requires a preview and explicit confirmation from you.</small></span></label>{consent&&<label>{member.phone_last_four?"Replace phone number (optional)":"Phone number"}<input required={!member.phone_last_four} value={phone} onChange={(event)=>setPhone(event.target.value.replace(/[\s()-]/g,""))} placeholder={member.phone_last_four?`Keep current number ending •••• ${member.phone_last_four}`:"+919876543210"}/><small>{member.phone_last_four?"Leave blank to keep the verified number already stored.":"Use E.164 format with country code."}</small></label>}{error&&<div className="form-message"><CircleAlert/>{error}</div>}<button className="primary full" disabled={busy}>{busy?<LoaderCircle className="spin"/>:<ShieldCheck/>}Save my callback settings</button></form></ModalShell>;
}
function CallModal({ session, company, member, onClose, onDone }: { session: Session; company: Company; member: Member; onClose: () => void; onDone: () => Promise<void> }) {
  const [mode,setMode]=useState<CallMode>("deposit"); const [focus,setFocus]=useState(""); const [stage,setStage]=useState<"compose"|"preview"|"calling"|"done">("compose"); const [preview,setPreview]=useState<Record<string,unknown>|null>(null); const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  async function prepare(){setBusy(true);setError("");try{const result=await apiFetch(session,"/api/callbacks/preview",{companyId:company.id,mode,focus});setPreview(result);setStage("preview");}catch(issue){setError(issue instanceof Error?issue.message:"Could not prepare the call.");}setBusy(false);}
  async function confirm(){if(!preview)return;setBusy(true);setError("");try{const result=await apiFetch(session,"/api/callbacks/confirm",{previewId:preview.previewId,fingerprint:preview.fingerprint});setPreview({...preview,...result});setStage(result.status==="completed"?"done":"calling");await onDone();}catch(issue){setError(issue instanceof Error?issue.message:"The call did not start.");}setBusy(false);}
  async function refresh(){if(!preview)return;setBusy(true);try{const result=await apiFetch(session,`/api/callbacks/status?id=${preview.previewId}`);setPreview({...preview,...result});if(["completed","failed","cancelled","canceled","no_answer","busy","declined","expired","voicemail"].includes(String(result.status)))setStage("done");await onDone();}catch(issue){setError(issue instanceof Error?issue.message:"Could not refresh status.");}setBusy(false);}
  return <ModalShell title="Talk to CALL-E" eyebrow="YOUR NUMBER · YOUR CONTEXT · YOUR APPROVAL" onClose={onClose}>{stage==="compose"&&<><div className="self-recipient"><span className="avatar">{initials(member.display_name)}</span><div><small>CALLING</small><b>{member.display_name}</b><p>{member.call_consent?`Verified number ending •••• ${member.phone_last_four}`:"Callbacks are not enabled yet"}</p></div><Check/></div><p className="modal-intro">What would be useful right now? CALL-E has access to this company’s typed memory and indexed sources, and the conversation can flow naturally.</p><div className="mode-list">{(Object.keys(modeCopy) as CallMode[]).map((item)=>{const Icon=modeCopy[item].icon;return <button type="button" key={item} className={mode===item?"active":""} onClick={()=>setMode(item)}><Icon/><span><b>{modeCopy[item].label}</b><small>{modeCopy[item].description}</small></span>{mode===item&&<Check/>}</button>;})}</div><label>Anything to focus on? <small>Optional</small><textarea rows={3} maxLength={600} value={focus} onChange={(event)=>setFocus(event.target.value)} placeholder="A launch decision, customer signal, blocker, or question you want to work through."/></label>{!member.call_consent&&<div className="eligibility no"><ShieldCheck/>Enable your callback number in personal settings first.</div>}{!supportedRegions.has(member.region)&&<div className="eligibility no"><CircleAlert/>CALL-E does not currently support callbacks in {member.region}.</div>}{error&&<div className="form-message"><CircleAlert/>{error}</div>}<button className="primary full" onClick={prepare} disabled={busy||!member.call_consent||!supportedRegions.has(member.region)}>{busy?<LoaderCircle className="spin"/>:<ArrowRight/>}Review my call</button></>}{stage==="preview"&&preview&&<><div className="call-preview"><span><small>RECIPIENT</small><b>{String(preview.recipient)}</b><p>{String(preview.maskedPhone)}</p></span><span><small>CONTEXT READY</small><b>{String(preview.contextItems)} items</b><p>{String(preview.duration)}</p></span><div><small>CONVERSATION GOALS</small>{Array.isArray(preview.questions)&&<ol>{preview.questions.map((question)=><li key={String(question)}>{String(question)}</li>)}</ol>}</div><div className="call-script"><small>EXACT CALL SCRIPT</small><pre>{String(preview.task)}</pre></div></div><div className="eligibility yes"><ShieldCheck/>{String(preview.warning)}</div>{error&&<div className="form-message"><CircleAlert/>{error}</div>}<div className="modal-actions"><button className="secondary" onClick={()=>setStage("compose")}>Back</button><button className="primary" onClick={confirm} disabled={busy}>{busy?<LoaderCircle className="spin"/>:<PhoneCall/>}Confirm this exact call</button></div></>}{stage==="calling"&&<div className="call-progress"><div className="pulse-ring"><PhoneCall/></div><h3>CALL-E is calling you</h3><p>The session runs outside this browser. Duplicate confirmations reconcile against one frozen payload and idempotency key.</p><button className="primary" onClick={refresh} disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Radio/>}Refresh call status</button></div>}{stage==="done"&&<div className="call-progress"><div className="done-ring"><Check/></div><h3>Session {String(preview?.status??"complete")}</h3><p>{String(preview?.summary??"The provider state has been saved. Only validated, evidence-supported results become typed company memory.")}</p><button className="primary" onClick={onClose}>Return to company</button></div>}</ModalShell>;
}
